// SPDX-License-Identifier: MIT
pragma solidity 0.8.7;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/BEP20Token.sol";

contract BEP20Token_OwnerPrivileges_Test is Test {
    BEP20Token token;
    address deployer;
    address rewardRecipient = address(0x2);
    uint256 initialSupply;

    function setUp() public {
        deployer = address(this);
        token = new BEP20Token();
        initialSupply = token.totalSupply();
    }

    function test_OwnerCanMintArbitraryTokens() public {
        uint256 mintAmount = 1000 * 10 ** token.decimals();

        uint256 initialBalance = token.balanceOf(deployer);
        uint256 initialTotalSupply = token.totalSupply();

        token.mint(mintAmount);

        assertEq(token.totalSupply(), initialTotalSupply + mintAmount, "Total supply not increased");
        assertEq(token.balanceOf(deployer), initialBalance + mintAmount, "Owner balance not increased");
    }

    function test_OwnerCanCallDistributeRewards() public {
        // Send only 100 wei to recipient to prevent overflow
        vm.deal(rewardRecipient, 100 wei);

        // Capture balance changes to verify transfer occurred
        uint256 initialOwnerBalance = token.balanceOf(deployer);
        uint256 initialRecipientBalance = token.balanceOf(rewardRecipient);

        // Owner can call the function and shouldn't revert
        token.distributeRewards(rewardRecipient);

        // Ensure tokens were transferred between accounts
        uint256 finalOwnerBalance = token.balanceOf(deployer);
        uint256 finalRecipientBalance = token.balanceOf(rewardRecipient);

        assertLt(finalOwnerBalance, initialOwnerBalance, "Owner token balance should decrease");
        assertGt(finalRecipientBalance, initialRecipientBalance, "Recipient token balance should increase");
        assertEq(
            finalRecipientBalance - initialRecipientBalance, 
            initialOwnerBalance - finalOwnerBalance, 
            "Tokens should transfer 1:1"
        );
    }
}
